@Composable private fun Grid(y:Int,m:Int,selected:Int,dots:Set<Int>,choose:(Int)->Unit){
 Row{(if(AppLanguage.code=="en")listOf("Sa","Su","Mo","Tu","We","Th","Fr")else listOf("ش","ی","د","س","چ","پ","ج")).forEach{Text(it,Modifier.weight(1f),textAlign=TextAlign.Center,fontSize=10.sp,color=MM)}}
 val first=Calendar.getInstance().apply{timeInMillis=PersianDate(y,m,1).toMillis()};val off=first.get(Calendar.DAY_OF_WEEK)%7
 repeat(6){w->Row{repeat(7){c->val d=w*7+c-off+1;if(d in 1..persianMonthDays(y,m))Surface(onClick={choose(d)},shape=CircleShape,color=if(d==selected)MP else Color.Transparent,border=if(d in dots&&d!=selected)BorderStroke(1.5.dp,MT)else null,modifier=Modifier.weight(1f).padding(2.dp).aspectRatio(1f)){Box(contentAlignment=Alignment.Center){Text(fa(d),fontSize=12.sp,color=if(d==selected)Color.White else MaterialTheme.colorScheme.onSurface)}}else Spacer(Modifier.weight(1f).aspectRatio(1f))}}}
}


@Composable fun MentoProfileScreen(vm:AppViewModel,auth:GoogleAuthManager,user:LocalGoogleUser?,setUser:(LocalGoogleUser?)->Unit,message:(String)->Unit,themeMode:String,setTheme:(String)->Unit,language:String,setLanguage:(String)->Unit,modifier:Modifier){
 val c=LocalContext.current;val scope=rememberCoroutineScope();var edit by remember{mutableStateOf(false)};var themeDialog by remember{mutableStateOf(false)};var languageDialog by remember{mutableStateOf(false)}
 var name by remember(user){mutableStateOf(user?.name?:tx("کاربر Mento","Mento user"))};var photo by remember(user){mutableStateOf(user?.picture)}
