 var restoreUri by remember{mutableStateOf<Uri?>(null)};var backupSummary by remember{mutableStateOf<BackupSummary?>(null)}
 val pick=rememberLauncherForActivityResult(ActivityResultContracts.OpenDocument()){u:Uri?->u?.let{runCatching{c.contentResolver.takePersistableUriPermission(it,Intent.FLAG_GRANT_READ_URI_PERMISSION)};photo=it.toString()}}
 val notify=rememberLauncherForActivityResult(ActivityResultContracts.RequestPermission()){message(if(it)tx("اعلان‌ها فعال شدند","Notifications enabled") else tx("دسترسی اعلان داده نشد","Notification permission was not granted"))}
 val export=rememberLauncherForActivityResult(ActivityResultContracts.CreateDocument("application/octet-stream")){u:Uri?->u?.let{vm.export(it,password){r->message(r.fold({tx("بکاپ ذخیره شد","Backup saved")},{e->e.message?:tx("خطا","Something went wrong")}))}}}
 val restore=rememberLauncherForActivityResult(ActivityResultContracts.OpenDocument()){u:Uri?->u?.let{uri->restoreUri=uri;vm.inspectBackup(uri,password){r->r.onSuccess{backupSummary=it}.onFailure{message(it.message?:tx("فایل بکاپ معتبر نیست","Invalid backup file"))}}}}
 LazyColumn(modifier.fillMaxSize().padding(16.dp),verticalArrangement=Arrangement.spacedBy(10.dp),contentPadding=PaddingValues(bottom=90.dp)){
  item{Text(tx("پروفایل","Profile"),fontSize=21.sp,fontWeight=FontWeight.ExtraBold)}
  item{Card(shape=RoundedCornerShape(22.dp),colors=CardDefaults.cardColors(MaterialTheme.colorScheme.surface),border=BorderStroke(1.dp,MaterialTheme.colorScheme.outline)){Column(Modifier.fillMaxWidth().padding(18.dp),horizontalAlignment=Alignment.CenterHorizontally){Avatar(name,photo,82);Spacer(Modifier.height(10.dp));Text(name,fontWeight=FontWeight.Bold,fontSize=18.sp);Text(user?.email?.ifBlank{user.phone?:tx("حساب محلی","Local account")}?:tx("حساب محلی","Local account"),fontSize=12.sp,color=MM);OutlinedButton({edit=true},Modifier.padding(top=10.dp)){Icon(Icons.Outlined.Edit,null);Spacer(Modifier.width(6.dp));Text(tx("ویرایش پروفایل","Edit profile"))}}}}
  item{Action(Icons.Outlined.AccountCircle,if(user?.provider=="google")tx("حساب Google متصل است","Google account connected") else tx("اتصال حساب Google","Connect Google account"),if(user?.provider=="google")user.email else tx("اختیاری؛ داده‌های مالی همچنان محلی‌اند","Optional. Financial data stays on this phone.")){
   if(user?.provider!="google"){if(!auth.configured)message(tx("OAuth تنظیم نشده","Google sign-in is not configured"))else scope.launch{runCatching{auth.signIn(c as Activity)}.onSuccess{setUser(it);name=it.name;photo=it.picture}.onFailure{message(it.message?:tx("ورود ناموفق","Sign-in failed"))}}}
   else scope.launch{auth.signOut();setUser(null);message(tx("خارج شدید؛ داده‌ها حذف نشد","Signed out. Your data is still on this phone."))}
  }}
  item{Action(Icons.Outlined.Notifications,tx("مجوز اعلان","Notification permission"),tx("یادآوری سررسیدها","Payment reminders")){if(Build.VERSION.SDK_INT>=33)notify.launch(Manifest.permission.POST_NOTIFICATIONS)else message(tx("اعلان‌ها فعال‌اند","Notifications are enabled"))}}
  item{Action(Icons.Outlined.Alarm,tx("مجوز آلارم دقیق","Exact alarm permission"),tx("اجرای هشدار در ساعت انتخابی","Remind me at the selected time")){if(Build.VERSION.SDK_INT>=31)c.startActivity(Intent(Settings.ACTION_REQUEST_SCHEDULE_EXACT_ALARM,Uri.parse("package:${c.packageName}")))}}
  item{Action(Icons.Outlined.BatterySaver,tx("بهینه‌سازی باتری","Battery optimization"),tx("اگر یادآورها دیر اجرا می‌شوند، محدودیت باتری Mento را بررسی کنید","If reminders are delayed, check Mento’s battery restrictions.")){c.startActivity(Intent(Settings.ACTION_IGNORE_BATTERY_OPTIMIZATION_SETTINGS))}}
  item{Action(Icons.Outlined.DarkMode,"ظاهر برنامه",when(themeMode){"dark"->"تیره";"light"->"روشن";else->"هماهنگ با گوشی"}){themeDialog=true}}
  item{Action(Icons.Outlined.Language,tx("زبان برنامه","App language"),if(language=="en")"English" else "فارسی"){languageDialog=true}}
  item{Action(Icons.Outlined.Backup,tx("بکاپ رمزدار","Encrypted backup"),tx("ذخیره روی گوشی","Save on this phone")){password="";passwordMode="export"}}
  item{Action(Icons.Outlined.Restore,tx("بازیابی بکاپ","Restore backup"),tx("از فایل Mento","From a Mento backup file")){password="";passwordMode="import"}}
  item{Surface(color=MS,shape=RoundedCornerShape(16.dp)){Text(tx("ورود یا خروج Google داده‌های مالی را حذف نمی‌کند. پیش از حذف برنامه بکاپ بگیرید.","Signing in or out of Google keeps your financial data. Create a backup before uninstalling Mento."),Modifier.padding(14.dp),fontSize=11.sp,color=MM)}}
 }
 if(edit)AlertDialog(onDismissRequest={edit=false},title={Text(tx("ویرایش پروفایل","Edit profile"))},text={Column(horizontalAlignment=Alignment.CenterHorizontally){Avatar(name,photo,76);TextButton({pick.launch(arrayOf("image/*"))}){Text(tx("انتخاب عکس","Choose photo"))};OutlinedTextField(name,{name=it},label={Text(tx("نام نمایشی","Display name"))})}},confirmButton={Button({auth.saveProfile(name,photo);setUser(auth.currentUser());edit=false;message(tx("پروفایل ذخیره شد","Profile saved"))}){Text(tx("ذخیره","Save"))}},dismissButton={TextButton({edit=false}){Text(tx("انصراف","Cancel"))}})
 if(themeDialog)AlertDialog(onDismissRequest={themeDialog=false},title={Text(tx("ظاهر برنامه","Appearance"))},text={Column{listOf("system" to "هماهنگ با گوشی","light" to "روشن","dark" to "تیره").forEach{(key,label)->Row(Modifier.fillMaxWidth().clickable{setTheme(key);themeDialog=false}.padding(12.dp),verticalAlignment=Alignment.CenterVertically){RadioButton(themeMode==key,{setTheme(key);themeDialog=false});Text(lx(label))}}}},confirmButton={TextButton({themeDialog=false}){Text(tx("بستن","Close"))}})
 if(languageDialog)AlertDialog(onDismissRequest={languageDialog=false},title={Text(tx("زبان برنامه","App language"))},text={Column{listOf("fa" to "فارسی","en" to "English").forEach{(key,label)->Row(Modifier.fillMaxWidth().clickable{setLanguage(key);languageDialog=false}.padding(12.dp),verticalAlignment=Alignment.CenterVertically){RadioButton(language==key,{setLanguage(key);languageDialog=false});Text(lx(label))}}}},confirmButton={TextButton({languageDialog=false}){Text(tx("بستن","Close"))}})
 if(passwordMode!=null)AlertDialog(onDismissRequest={passwordMode=null},title={Text(tx("رمز بکاپ","Backup password"))},text={OutlinedTextField(password,{password=it},label={Text(tx("رمز","Password"))})},confirmButton={TextButton({if(passwordMode=="export"&&password.length<6)message(tx("حداقل ۶ کاراکتر","Use at least 6 characters"))else{val mode=passwordMode;passwordMode=null;if(mode=="export")export.launch("mento-backup-${PersianDate.from()}.mento")else restore.launch(arrayOf("application/octet-stream","application/zip"))}}){Text(tx("ادامه","Continue"))}},dismissButton={TextButton({passwordMode=null}){Text(tx("انصراف","Cancel"))}})
 backupSummary?.let{summary->AlertDialog(onDismissRequest={backupSummary=null;restoreUri=null},title={Text(tx("پیش‌نمایش بکاپ","Backup preview"))},text={Column(verticalArrangement=Arrangement.spacedBy(8.dp)){Text(tx("${fa(summary.items)} آیتم پرداخت","${fa(summary.items)} payments"));Text(tx("${fa(summary.installments)} قسط","${fa(summary.installments)} installments"));Text(tx("${fa(summary.receipts)} فایل رسید","${fa(summary.receipts)} receipt files"));Text(tx("ادغام، اطلاعات فعلی را نگه می‌دارد. جایگزینی، اطلاعات فعلی را پاک می‌کند.","Merge keeps your existing data. Replace removes your existing data."),fontSize=11.sp,color=MM)}},confirmButton={Row{TextButton({val u=restoreUri?:return@TextButton;backupSummary=null;vm.import(u,password,false){r->message(r.fold({tx("بکاپ با اطلاعات فعلی ادغام شد","Backup merged with existing data")},{e->e.message?:tx("خطا","Something went wrong")}))}}){Text(tx("ادغام","Merge"))};TextButton({val u=restoreUri?:return@TextButton;backupSummary=null;vm.import(u,password,true){r->message(r.fold({tx("بکاپ جایگزین شد","Backup restored")},{e->e.message?:tx("خطا","Something went wrong")}))}}){Text(tx("جایگزینی","Replace"),color=MR)}}},dismissButton={TextButton({backupSummary=null;restoreUri=null}){Text(tx("انصراف","Cancel"))}})}
}
@Composable private fun Avatar(name:String,uri:String?,size:Int){val c=LocalContext.current;val b=remember(uri){uri?.let{runCatching{c.contentResolver.openInputStream(Uri.parse(it))?.use(BitmapFactory::decodeStream)?.asImageBitmap()}.getOrNull()}};Surface(color=MS,shape=CircleShape,modifier=Modifier.size(size.dp)){if(b!=null)Image(b,null,Modifier.fillMaxSize(),contentScale=androidx.compose.ui.layout.ContentScale.Crop)else Box(contentAlignment=Alignment.Center){Text(name.trim().take(1).ifBlank{"م"},fontSize=(size/3).sp,fontWeight=FontWeight.Bold,color=MP)}}}
@Composable private fun Action(i:ImageVector,t:String,s:String,click:()->Unit){Card(onClick=click,shape=RoundedCornerShape(17.dp),colors=CardDefaults.cardColors(MaterialTheme.colorScheme.surface),border=BorderStroke(1.dp,MaterialTheme.colorScheme.outline)){Row(Modifier.fillMaxWidth().padding(14.dp),verticalAlignment=Alignment.CenterVertically){Icon(i,null,tint=MP);Spacer(Modifier.width(11.dp));Column(Modifier.weight(1f)){Text(lx(t),fontWeight=FontWeight.Bold);Text(lx(s),fontSize=10.sp,color=MM)};Icon(Icons.Outlined.ChevronLeft,null,tint=MM)}}}
@Composable private fun Empty(t:String){Surface(shape=RoundedCornerShape(18.dp),color=MaterialTheme.colorScheme.surface,border=BorderStroke(1.dp,MaterialTheme.colorScheme.outline)){Text(lx(t),Modifier.fillMaxWidth().padding(26.dp),textAlign=TextAlign.Center,fontSize=12.sp,color=MaterialTheme.colorScheme.onSurfaceVariant)}}
